for task in records:

    # 1. Obtenemos el origen desde la Orden de Venta
    if not task.sale_order_id:
        continue

    sale_origin = task.sale_order_id.name

    # 2. Buscamos la ENTREGA "Hecha" (done) con tu tipo de operación específico
    delivery_done = env['stock.picking'].search([
        ('origin', '=', sale_origin),
        ('state', '=', 'done')
    ], limit=1)

    if delivery_done:
        # 3. Buscamos la etapa destino "Hecho"
        target_stage = env['project.task.type'].search([
            ('name', '=', 'Hecho'),
            ('project_ids', 'in', task.project_id.id)
        ], limit=1)

        # Fallback genérico
        if not target_stage:
            target_stage = env['project.task.type'].search([('name', '=', 'Hecho')], limit=1)

        # 4. Actualizamos la tarea
        if target_stage and task.stage_id.id != target_stage.id:
            task.write({
                'stage_id': target_stage.id,
                'state': '1_done'  # REEMPLAZO: En Odoo nuevo, esto marca la tarea como finalizada
            })

            task.message_post(body=f"Tarea pasada a Hecho automáticamente. Entrega validada: {delivery_done.name}")

